// Jerarquía de ejemplo con nombres inventados: organización > carpetas > proyectos.
// Cada nodo puede conceder roles a personas; los roles se heredan hacia abajo.
const arbol = {
  n: 'organizacion/empresa', da: { ana: ['owner'] },
  h: [
    { n: 'carpeta/produccion', da: { redes: ['networkAdmin'] }, h: [
      { n: 'proyecto/tienda-prod', da: { beto: ['editor'] }, h: [] },
    ]},
    { n: 'carpeta/pruebas', da: {}, h: [
      { n: 'proyecto/tienda-test', da: { beto: ['owner'] }, h: [] },
    ]},
  ],
};
function recorrer(nodo, heredado, salida) {
  const aqui = {};
  for (const [p, r] of Object.entries(heredado)) aqui[p] = [...r];
  for (const [p, r] of Object.entries(nodo.da)) aqui[p] = [...(aqui[p] || []), ...r];
  if (nodo.h.length === 0) salida[nodo.n] = aqui;
  for (const hijo of nodo.h) recorrer(hijo, aqui, salida);
  return salida;
}
const efectivos = recorrer(arbol, {}, {});
for (const [proy, quien] of Object.entries(efectivos)) {
  console.log(proy);
  for (const [p, roles] of Object.entries(quien)) console.log('  ' + p + ': ' + roles.join(', '));
}

// Tabla inventada de 5.000 millones de filas de envíos. Tamaños según la tabla de BigQuery:
// INT64 8 bytes, TIMESTAMP 8, FLOAT64 8, STRING 2 bytes + largo en UTF-8.
const filas = 5e9;
const columnas = {
  id: 8, fecha: 8, deposito: 2 + 8, estado: 2 + 9, peso_kg: 8, observaciones: 2 + 200,
};
const TIB = 2 ** 40, PRECIO_TIB = 6.25;
function costo(cols) {
  const bytes = cols.reduce((s, c) => s + columnas[c], 0) * filas;
  const tib = bytes / TIB;
  return { gb: (bytes / 2 ** 30).toFixed(0), tib: tib.toFixed(3), usd: (tib * PRECIO_TIB).toFixed(2) };
}
const todas = Object.keys(columnas);
console.log('SELECT estado, COUNT(*) ...  ->', costo(['estado']));
console.log('SELECT estado, AVG(peso_kg)  ->', costo(['estado', 'peso_kg']));
console.log('SELECT *                     ->', costo(todas));
